let numbers = [10, 20, 30];
console.log('Original:', numbers);

// Remove the last item (30)
numbers.pop();
console.log('After pop:', numbers);

// Add item to the start (5)
numbers.unshift(5);
console.log('After unshift:', numbers);

// Remove item from the start (5)
numbers.shift();
console.log('After shift:', numbers);

let cart = ['Apple', 'Banana', 'Cherry'];

// i starts at 0.
// It runs as long as i < 3 (the length of the array)
// i increments by 1 each time.
for (let i = 0; i < cart.length; i++) {

  // cart[i] will be cart[0], then cart[1], then cart[2]
  let currentItem = cart[i];

  console.log('Processing item:', currentItem);
}

// Creating an object using curly braces
let userProfile = {
  // Key: Value
  name: 'John Doe',
  email: 'admin@corp.com',
  age: 30,
  isActive: true
};

// Accessing object data using Dot Notation (.)
console.log(userProfile.name);
console.log(userProfile.email);

let user = {
  name: 'John',
  age: 30
};
console.log('Original Age:', user.age);

// 1. Updating an existing property
user.age = 31;
console.log('Updated Age:', user.age);

// 2. Adding a completely new property
user.city = 'New York';
console.log('Added City:', user.city);

// 3. Using bracket notation for dynamic keys
let keyToUpdate = 'age';
user[keyToUpdate] = 32;

let car = {
  brand: 'Toyota',
  color: 'Red',

  // This is a Method
  start: function() {
    console.log('Engine started. Vroom!');
  },

  // Method using 'this' to access object properties
  drive: function() {
    console.log('The ' + this.brand + ' is driving.');
  }
};

// Calling the methods
car.start();
car.drive();

