// Assuming our HTML has: <h1 id="main-title">Hello</h1>
// and: <button class="submit-btn">Submit</button>

// 1. Select by ID
let titleElement = document.getElementById('main-title');
console.log('Selected Heading Element');

// 2. Select using a CSS class selector
let buttonElement = document.querySelector('.submit-btn');
