// 1. Select the elements
let title = document.getElementById('main-title');
let box = document.querySelector('.content-box');

// 2. Change raw text
title.innerText = 'JavaScript is Awesome!';
console.log("Title text changed");

// 3. Inject HTML markup
box.innerHTML = '<strong>Warning:</strong> System Error';
