let box = document.querySelector('.box');

// Modifying Inline Styles
// 'background-color' becomes 'backgroundColor'
box.style.backgroundColor = 'blue';
box.style.fontSize = '24px';
box.style.display = 'block';

// Using the ClassList API (Best Practice)
// Assuming '.hidden' and '.active' exist in CSS
box.classList.remove('hidden');
box.classList.add('active');

console.log('Styles updated successfully.');

// 1. Select the button element
let submitBtn = document.querySelector('.submit-btn');

// 2. Create the function that will run when clicked
function handleClick() {
  console.log('Button was clicked! Executing code...');
}

// 3. Attach the Event Listener to the button
// Format: element.addEventListener('eventName', functionToRun);
submitBtn.addEventListener('click', handleClick);

